tennis_set = TennisSet(('A', 'B'))
def win_game(player):
    for _ in range(4):
        tennis_set.record_point(player)
for _ in range(6):
    win_game('A')
    win_game('B')
assert isinstance(tennis_set.current_game, TiebreakGame)
for _ in range(5):
    tennis_set.record_point('A')
    tennis_set.record_point('B')
tennis_set.record_point('A')
tennis_set.record_point('A')
assert tennis_set.complete and tennis_set.winner == 'A'
assert tennis_set.games_won == {'A': 7, 'B': 6}

match = Match(('A', 'B'), best_of=3)
for _ in range(2):
    for _ in range(6):
        for _ in range(4):
            match.record_point('A')
assert match.complete and match.winner == 'A'
assert match.sets_won == {'A': 2, 'B': 0}
assert match.state()['complete'] is True
for call in (lambda: match.record_point('A'), lambda: Match(('A', 'A')), lambda: Match(('A', 'B'), best_of=2)):
    try:
        call()
        raise AssertionError('expected an error')
    except (RuntimeError, ValueError):
        pass
